import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Doygunluk, renklerin ne kadar canlı göründüğünü belirler. Soluk fotoğrafı canlandırır, cıvıl cıvıl fotoğrafı sakinleştirir.</p>\n<p>Doğru doygunluk, fotoğrafı doğal gösterir. Yanlış doygunluk ise renkleri yapay yapar ve cildi turuncu gösterir.</p>\n<p>Bu kılavuz, doygunluk kaydırıcısının nasıl çalıştığını, hızlı ön ayarları ve ten renklerini korumanın yollarını anlatıyor.</p>\n<h2 id=\"what-saturation-does\">Doygunluk gerçekte ne yapar?</h2>\n<p>Doygunluk, renklerin yoğunluğunu artırır ya da azaltır. Kırmızı daha kırmızı, mavi daha mavi olur.</p>\n<p>Doygunluk artırmak, soluk fotoğrafı canlandırır. Doygunluk azaltmak, renkleri soldurur.</p>\n<p>Doygunluk sıfır olursa fotoğraf siyah beyaz olur. Renk tamamen gider.</p>\n<h2 id=\"why-photos-look-dull\">Fotoğraflar neden soluk çıkar?</h2>\n<p>Bulutlu hava, renkleri soldurur. Işık dağılır; renkler cansız görünür.</p>\n<p>Eski taramalar da soluk olabilir. Zamanla solan fotoğraflar, doygunluğunu kaybeder.</p>\n<p>Yanlış beyaz dengesi de renkleri bozar. Fotoğraf, sarı ya da mavi görünür.</p>\n<h2 id=\"slider-explained\">Doygunluk kaydırıcısı, açıklanıyor</h2>\n<p>Doygunluk kaydırıcısı -100 ile +100 arasında çalışır. Sıfır, fotoğrafın ilk hâlidir.</p>\n<p>Araçta doygunluğu küçük adımlarla yükseltin; soluk fotoğrafların çoğu +10 ile +20 arasında düzelir.</p>\n<p>Araçta doygunluğu +50'nin üstüne çıkarmayın; aşırı değerler, renkleri yapay yapar.</p>\n<h2 id=\"quick-presets\">Tek tıkla renk için hızlı ön ayarlar</h2>\n<p>Araçtaki hızlı ön ayarlarla başlayın; canlı, doğal ve soluk seçenekleri hazır bekler.</p>\n<p>Ön ayarı seçin, sonra kaydırıcıyla ince ayar yapın. Ön ayar yalnızca bir başlangıçtır.</p>\n<p>Kendi ön ayarınızı saklayın. Aynı renk düzeltmesini sık yapıyorsanız zaman kazanırsınız.</p>\n<h2 id=\"muted-vs-grayscale\">Soluk ve siyah beyaz: rengi almanın iki yolu</h2>\n<p>Soluk görünüm, doygunluğu azaltır ama renk kalır. Zarif ve sakin bir his verir.</p>\n<p>Araçta siyah beyazı seçerseniz doygunluk sıfırlanır; renk tamamen gider, geriye yalnızca açık ve koyu tonlar kalır.</p>\n<p>Seçim, amaca bağlıdır. Zarif görünüm için soluk, dramatik görünüm için siyah beyaz kullanın.</p>\n<h2 id=\"hyper-saturation\">Aşırı doygunluk: fazla, çok fazladır</h2>\n<p>Aşırı doygunluk, renkleri yapay yapar. Çimen neon yeşil, gökyüzü elektrik mavisi olur.</p>\n<p>Ten renkleri ilk bozulanlardır. Yüz turuncu görünür; bu, amatör işarettir.</p>\n<p>Sınırı bilin. +30'un üzeri, çoğu fotoğrafta yapay görünür.</p>\n<h2 id=\"saturation-and-skin\">Doygunluk ve ten renkleri</h2>\n<p>Ten renkleri, doygunluğa hassastır. Fazla doygunluk, cildi turuncu yapar.</p>\n<p>Araçta portre düzenlerken doygunluğu +10 ile +15 arasında tutun; cilt böylece doğal görünür.</p>\n<p>Araçta doygunluğu ayarlarken yüzü kontrol edin; ten rengi doğallığını yitirdiyse değeri düşürün.</p>\n<h2 id=\"saturation-for-landscapes\">Manzaralar için doygunluk</h2>\n<p>Manzaralarda doygunluğu +15 ile +25 arasında tutun. Gökyüzü ve çimen canlanır.</p>\n<p>Yeşili kontrol edin. Aşırı yeşil, yapay görünür.</p>\n<p>Gökyüzünü kontrol edin. Mavi, doğal kalmalıdır; elektrik mavisi yapaydır.</p>\n<h2 id=\"saturation-for-food\">Yemek fotoğrafları için doygunluk</h2>\n<p>Yemek fotoğraflarında doygunluğu +10 ile +20 arasında tutun. Yemek iştah açıcı görünmelidir.</p>\n<p>Kırmızıyı kontrol edin. Domates ve et, doğal kırmızı olmalıdır.</p>\n<p>Aşırı doygunluk, yemeği sahte gösterir. Doğal renk, güven verir.</p>\n<h2 id=\"saturation-for-products\">Ürün fotoğrafları için doygunluk</h2>\n<p>Araçta ürün fotoğrafı düzenlerken renk doğruluğuna dikkat edin; müşteri, ekranda gördüğü rengi teslim almalıdır.</p>\n<p>Araçta doygunluğu +5 ile +10 arasında tutun; ürün fotoğrafında renk, gerçeği yansıtmalıdır.</p>\n<p>Düzenleme bitince ürünü elinize alıp ekrandaki renkle karşılaştırın; ikisi aynı görünmelidir.</p>\n<h2 id=\"desaturating-photos\">Soluk ve zarif görünüm için doygunluğu azaltmak</h2>\n<p>Doygunluğu azaltmak, zarif görünüm yaratır. -10 ile -20 arası, sakin bir his verir.</p>\n<p>Araçta düğün ve portrelerde soluk ayarı deneyin; yumuşak renkler, bu karelerde zarif durur.</p>\n<p>Araçta soluk ayarı ölçülü tutun; fazla soluk bırakılan fotoğraf, cansız ve yorgun görünür.</p>\n<h2 id=\"saturation-and-brightness\">Doygunluk, parlaklık ve algılanan ışık</h2>\n<p>Doygunluk artınca fotoğraf daha parlak görünür. Renkler canlı olunca ışık da canlı algılanır.</p>\n<p>Parlaklık ve doygunluğu birlikte ayarlayın. İkisi birbirini etkiler; dengeyi birlikte bulun.</p>\n<p>Koyu fotoğrafta önce parlaklığı ayarlayın. Sonra doygunluğu kontrol edin.</p>\n<h2 id=\"formats-and-export\">Formatlar ve dışa aktarma</h2>\n<p>Rengi ayarlanan fotoğraflar için JPG kullanın. Dosya küçüktür ve her yerde açılır.</p>\n<p>Saydam görselleri PNG biçiminde indirin. JPG saydamlığı desteklemez.</p>\n<p>Dışa aktarmadan önce önizlemeyi kontrol edin. Renkler doğal görünmelidir.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden düzenlemek</h2>\n<p>Doygunluk aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Özel fotoğraflarda bu güvence değerlidir. Aile ve müşteri görsellerini güvenle renklendirebilirsiniz.</p>\n<p>İşlem tamamlanınca tarayıcı temizlenir. Fotoğraflarınız sizde kalır.</p>\n<h2 id=\"common-mistakes\">Doygunluk ayarlarken yaygın hatalar</h2>\n<p>Araçta en sık yapılan hata, doygunluğu abartmaktır; +50'nin üzeri, renkleri yapay ve sahte gösterir.</p>\n<p>Bir başka hata, ten renklerini bozmaktır. Portrelerde doygunluğu düşük tutun.</p>\n<p>Üçüncü hata, orijinal dosyayı silmektir. Düzenlenen fotoğraf ayrıdır; orijinali saklayın.</p>\n<h2 id=\"saturation-workflow\">Doğal renk için bir akış</h2>\n<p>Önce fotoğrafın ne kadar soluk olduğunu değerlendirin. Hafif soluksa +10, çok soluksa +20 kullanın.</p>\n<p>Sonra kaydırıcıyla ince ayar yapın. Karşılaştırma modunda farkı izleyin.</p>\n<p>Son olarak ten renklerini kontrol edin. Cilt doğal görünmelidir.</p>\n<h2 id=\"saturation-for-weddings\">Düğün fotoğrafları için doygunluk</h2>\n<p>Düğün fotoğraflarında doygunluğu düşük tutun. +5 ile +10 arası, zarif görünür.</p>\n<p>Gelinliği kontrol edin. Beyaz, doğal kalmalıdır; sarı ya da mavi olmamalıdır.</p>\n<p>Soluk görünüm, düğünlerde yaygındır. Yumuşak renkler, zarif durur.</p>\n<p>Özetle: az doygunluk ekleyin, ten renklerini izleyin, doğallığı koruyun. Adımlar için <a href=\"/tr/blog/gorsel-doygunlugu-nasil-ayarlanir\">Görsel doygunluğu nasıl ayarlanır</a> yazısına bakın; karşılaştırma için <a href=\"/tr/blog/doygunluk-vs-canlilik\">doygunluk ve canlılık karşılaştırması</a> yardımcı olur. Filtreler için <a href=\"/tr/gorsel-filtreleri\">görsel filtreler</a> hazırdır; araç ise <a href=\"/tr/gorsel-doygunluk-ayarla\">görsel doygunluk düzenleyici</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Soluk bir fotoğrafa ne kadar doygunluk eklemeliyim?","answer":"Genellikle +10 ile +20 arası yeterlidir. Küçük adımlarla ayarlayın ve karşılaştırma moduyla farkı izleyin. +30'un üzeri çoğu fotoğrafta renkleri yapay yapar."},{"question":"Portrem doygunluğu artırdıktan sonra neden turuncu görünüyor?","answer":"Çünkü ten renkleri doygunluğa hassastır; fazla doygunluk cildi turuncu yapar. Portrelerde doygunluğu +10 ile +15 arasında tutun. Canlılık kontrolü, ten renklerini koruyarak çalışır."},{"question":"Soluk ile siyah beyaz arasındaki fark nedir?","answer":"Soluk görünüm doygunluğu azaltır ama renk kalır; zarif ve sakin his verir. Siyah beyaz doygunluğu sıfırlar; renk tamamen gider. Seçim amaca bağlıdır; zarif için soluk, dramatik için siyah beyaz kullanın."},{"question":"Doygunluk kötü ışıkla çekilen bir fotoğrafı düzeltebilir mi?","answer":"Kısmen. Doygunluk renkleri canlandırır ama kaybolan ayrıntıyı geri getirmez. Önce parlaklığı ayarlayın, sonra doygunluğu kontrol edin. Çok koyu fotoğrafta doygunluk tek başına yeterli olmaz."},{"question":"Doygunluğu değiştirmek fotoğrafımın parlaklığını etkiler mi?","answer":"Evet, dolaylı olarak. Doygunluk artınca fotoğraf daha parlak görünür; renkler canlı olunca ışık da canlı algılanır. Parlaklık ve doygunluğu birlikte ayarlayın."},{"question":"Kişisel bir fotoğrafın doygunluğunu tarayıcı aracında düzenlemek güvenli mi?","answer":"Evet. Araç tamamen tarayıcıda çalışır; fotoğraflarınız sunucuya yüklenmez. İş bitince tarayıcı verisi silinir. Özel fotoğrafları güvenle düzenleyebilirsiniz."}];
